const T = Math.max(P.T, 1);
const k = 1.380649e-23;
const m = 4.65e-26; // N2 molecule mass (kg)
const vrms = Math.sqrt(3 * k * T / m);
const a = m / (2 * k * T);
const peak = Math.sqrt(2 / a);
const fmax = 4 * Math.PI * Math.pow(a / Math.PI, 1.5) * peak * peak * Math.exp(-a * peak * peak);
v.fn(s => {
  const f = 4 * Math.PI * Math.pow(a / Math.PI, 1.5) * s * s * Math.exp(-a * s * s);
  return f / (fmax * 1.05);
}, { color: H.colors.accent, width: 3 });
